layer.fontFaces:
@font-face { font-family: inter; font-style: normal; font-weight: 400; font-display: swap; src: url("{{assets}}/docura_997bcc9ea3ed/Inter-Regular.woff2") format("woff2"), url("{{assets}}/docura_997bcc9ea3ed/Inter-Regular.woff") format("woff"); }
@font-face { font-family: inter; font-style: italic; font-weight: 400; font-display: swap; src: url("{{assets}}/docura_997bcc9ea3ed/Inter-Italic.woff2") format("woff2"), url("{{assets}}/docura_997bcc9ea3ed/Inter-Italic.woff") format("woff"); }
@font-face { font-family: inter; font-style: normal; font-weight: 600; font-display: swap; src: url("{{assets}}/docura_997bcc9ea3ed/Inter-SemiBold.woff2") format("woff2"), url("{{assets}}/docura_997bcc9ea3ed/Inter-SemiBold.woff") format("woff"); }

layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(247, 247, 247); border-left: 4px solid rgb(221, 221, 221); border-radius: 6px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: -0.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: -0.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(39, 68, 87); font-family: var(--ryt-font-heading); font-size: 48px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(39, 68, 87); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(39, 68, 87); border-radius: 0px; font-family: Times, serif; font-size: 22.4px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(39, 68, 87); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(71, 109, 134); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(71, 109, 134); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 12px; padding-right: 6px; padding-bottom: 12px; padding-left: 6px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(39, 68, 87); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(39, 68, 87); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { border-bottom-width: 3px; border-bottom-style: solid; border-bottom-color: currentcolor }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
